window.EXAM = {"meta":{"testId":"y10-cs-end-of-term-test","title":"End-of-Term Test","subtitle":"Algorithms, programming, data structures, shifts and compression","course":"Cambridge IGCSE Computer Science (0478)","year":"Year 10","subject":"Computer Science","durationMinutes":40,"gradeBoundaries":[{"grade":"A*","min":78},{"grade":"A","min":62},{"grade":"B","min":46},{"grade":"C","min":30.7},{"grade":"D","min":26},{"grade":"E","min":21.3},{"grade":"F","min":16.7},{"grade":"G","min":12}],"instructions":["Answer <b>all</b> the questions. There is no typing: you click, choose from drop-down lists or switch bits on and off.","Use your pen and paper for trace tables and working out. Only what you choose on screen is marked.","The number of marks for each question is shown in brackets [ ].","All pseudocode uses the Cambridge IGCSE (0478) conventions. Arrays start at index 1.","Not sure? Press <b>Flag</b> and come back to it. The numbered buttons at the top take you to any question.","Your answers save automatically. When the timer reaches 0:00 your test is handed in automatically."]},"sections":[{"id":"data","name":"Shifts and compression","desc":"Logical binary shifts, run-length encoding, compression ratio"},{"id":"sel","name":"Selection and Boolean logic","desc":"AND, OR, NOT, ELSE IF, CASE OF"},{"id":"loop","name":"Loops","desc":"WHILE, REPEAT … UNTIL, choosing a loop, nested loops"},{"id":"arr","name":"Arrays","desc":"1D arrays (total, average, count, highest, lowest) and 2D arrays with nested loops"},{"id":"alg","name":"Searching and sorting","desc":"Linear search and bubble sort"},{"id":"str","name":"Strings and maths","desc":"LENGTH, SUBSTRING, UCASE, MOD, DIV, ROUND"},{"id":"sub","name":"Procedures, functions and files","desc":"FUNCTION, RETURNS, RETURN, parameters, OPENFILE, WRITEFILE, CLOSEFILE"}],"skills":[{"id":"AO1","name":"AO1 Knowledge and understanding"},{"id":"AO2","name":"AO2 Applying knowledge"},{"id":"AO3","name":"AO3 Designing algorithms"}],"questions":[{"num":1,"section":"data","stem":"This question is about logical shifts and compression.","parts":[{"id":"1a","label":"(a)","type":"bits","marks":1,"prompt":"Show the contents of the register after a <b>logical right shift of two places</b>. Click the bits to switch them between 0 and 1.","lead":"An 8-bit register contains <code class=\"big\">01011010</code> (denary 90).","n":8},{"id":"1b","label":"(b)","type":"mcq","marks":1,"prompt":"What is the denary value of the register after the shift in (a)?","options":[{"id":"o1np7","text":"22"},{"id":"o6rnh","text":"22.5"},{"id":"o1ykv","text":"45"},{"id":"o16o9","text":"360"}]},{"id":"1c","label":"(c)","type":"mcq","marks":1,"prompt":"The register <code>11000001</code> (denary 193) is given a logical <b>left</b> shift of one place. What happens?","options":[{"id":"ojrnk","text":"The left-most 1 is lost, so the result (130) is not 2 × 193."},{"id":"o1y2x","text":"The result is 386, which is 2 × 193."},{"id":"o4pgt","text":"A 1 enters on the right, so the result is 131."},{"id":"o1xo5","text":"Nothing changes, because the left-most bit is 1."}]},{"id":"1d","label":"(d)","type":"mcq","marks":1,"prompt":"Which is the run-length encoded version of this row?","lead":"One row of a black-and-white image is: <code class=\"big\">WWWWWBBWWWWWWW</code><br>The RLE method stores each run as a <b>count</b> followed by the <b>colour</b>.","options":[{"id":"o15gy","text":"5W2B7W","code":true},{"id":"o1lld","text":"5W2B6W","code":true},{"id":"o1sp6","text":"W5B2W7","code":true},{"id":"o1kw2","text":"12W2B","code":true}]},{"id":"1e","label":"(e)","type":"mcq","marks":1,"prompt":"Each character uses 1 byte, and each count uses 1 byte. The original row is 14 bytes and the compressed row is 6 bytes. What is the <b>compression ratio</b> (original : compressed)?","options":[{"id":"okkxy","text":"7 : 3"},{"id":"o15lc","text":"3 : 7"},{"id":"o1ccn","text":"14 : 8"},{"id":"o1qc3","text":"2 : 1"}]},{"id":"1f","label":"(f)","type":"mcq","marks":1,"prompt":"Using the same RLE method, which data would become <b>larger</b> after compression?","options":[{"id":"ooz1y","text":"ABCDEF","code":true},{"id":"obgge","text":"AAAAAA","code":true},{"id":"olbw4","text":"AAABBB","code":true},{"id":"ouma8","text":"AAAAAB","code":true}]}]},{"num":2,"section":"sel","stem":"This question is about selection and Boolean logic.","parts":[{"id":"2a","label":"(a)","type":"tick","marks":2,"prompt":"Is each expression TRUE or FALSE?","lead":"<code>Age</code> stores <code>15</code> and <code>Member</code> stores <code>TRUE</code>.","columns":["TRUE","FALSE"],"rows":[{"text":"<code>Age &gt; 12 AND Age &lt; 16</code>"},{"text":"<code>Age &gt;= 16 OR Member</code>"},{"text":"<code>NOT Member</code>"},{"text":"<code>(Age &lt; 13 OR Age &gt; 19) AND Member</code>"}]},{"id":"2b","label":"(b)","type":"select","marks":2,"prompt":"This program should output <b>Valid</b> only if <code>Mark</code> is from 0 to 100 <b>inclusive</b>. Choose the missing parts.","code":true,"template":"INPUT Mark\nIF Mark {{0}} 0 {{1}} Mark {{2}} 100\n  THEN\n    OUTPUT \"Valid\"\n  ELSE\n    OUTPUT \"Invalid\"\nENDIF","gaps":[{"options":["<","<=",">",">="]},{"options":["AND","NOT","OR","THEN"]},{"options":["<","<=",">",">="]}]},{"id":"2c","label":"(c)","type":"select","marks":2,"prompt":"Choose the output for each pair of inputs.","listing":"INPUT Temp, Humidity\nIF Temp > 30 AND Humidity > 70\n  THEN\n    OUTPUT \"Storm risk\"\n  ELSE\n    IF Temp > 30\n      THEN\n        OUTPUT \"Hot\"\n      ELSE\n        OUTPUT \"Normal\"\n    ENDIF\nENDIF","template":"<table class=\"gt\"><tr><th><code>Temp</code></th><th><code>Humidity</code></th><th>Output</th></tr><tr><td class=\"given\">35</td><td class=\"given\">80</td><td>{{0}}</td></tr><tr><td class=\"given\">35</td><td class=\"given\">50</td><td>{{1}}</td></tr><tr><td class=\"given\">25</td><td class=\"given\">90</td><td>{{2}}</td></tr></table>","gaps":[{"options":["Storm risk","Hot","Normal"]},{"options":["Storm risk","Hot","Normal"]},{"options":["Storm risk","Hot","Normal"]}]},{"id":"2d","label":"(d)","type":"errline","marks":1,"prompt":"This program has <b>one</b> error. Click the line with the error.","lines":["INPUT Choice","CASE Choice OF","  1 : OUTPUT \"New game\"","  2 : OUTPUT \"Load game\"","  3 : OUTPUT \"Quit\"","  OTHERWISE : OUTPUT \"Invalid choice\"","ENDCASE"]}]},{"num":3,"section":"loop","stem":"This question is about loops.","parts":[{"id":"3a","label":"(a)","type":"select","marks":2,"prompt":"Complete the <code>Total</code> column of the trace table.","listing":"Total ← 0\nNum ← 1\nWHILE Total < 20 DO\n  Total ← Total + Num\n  Num ← Num + 2\nENDWHILE\nOUTPUT Total","template":"<table class=\"gt\"><tr><th><code>Num</code> (start of the loop)</th><th><code>Total</code> (end of the loop)</th></tr><tr><td class=\"given\"></td><td class=\"given\">0</td></tr><tr><td class=\"given\">1</td><td>{{0}}</td></tr><tr><td class=\"given\">3</td><td>{{1}}</td></tr><tr><td class=\"given\">5</td><td>{{2}}</td></tr><tr><td class=\"given\">7</td><td>{{3}}</td></tr><tr><td class=\"given\">9</td><td>{{4}}</td></tr></table>","gaps":[{"options":["1","3","4","9","12","16","20","25"]},{"options":["1","3","4","9","12","16","20","25"]},{"options":["1","3","4","9","12","16","20","25"]},{"options":["1","3","4","9","12","16","20","25"]},{"options":["1","3","4","9","12","16","20","25"]}]},{"id":"3b","label":"(b)","type":"mcq","marks":1,"prompt":"Which statement is correct?","options":[{"id":"oelr9","text":"A REPEAT … UNTIL loop always runs at least once; a WHILE loop might not run at all."},{"id":"o12tq","text":"A WHILE loop always runs at least once; a REPEAT … UNTIL loop might not run at all."},{"id":"o1r46","text":"Both loops always run a fixed number of times."},{"id":"o1pbl","text":"REPEAT … UNTIL checks its condition at the start of the loop."}]},{"id":"3c","label":"(c)","type":"select","marks":2,"prompt":"This code should keep asking until the user enters a number from 1 to 10. Choose the missing parts.","code":true,"template":"{{0}}\n  OUTPUT \"Enter a number from 1 to 10\"\n  INPUT Num\n{{1}} Num >= 1 {{2}} Num <= 10","gaps":[{"options":["FOR","REPEAT","WHILE","IF"]},{"options":["ENDWHILE","UNTIL","WHILE","NEXT"]},{"options":["AND","NOT","OR","THEN"]}]},{"id":"3d","label":"(d)","type":"errline","marks":1,"prompt":"This loop should stop after outputting 2, 4, 6, 8 and 10, but it never stops. Click the line that causes the problem.","lines":["Count ← 1","REPEAT","  Count ← Count + 2","  OUTPUT Count - 1","UNTIL Count = 10"]},{"id":"3e","label":"(e)","type":"mcq","marks":1,"prompt":"How many stars are output altogether?","listing":"FOR Row ← 1 TO 3\n  FOR Col ← 1 TO 4\n    OUTPUT \"*\"\n  NEXT Col\nNEXT Row","options":[{"id":"ou4pc","text":"4"},{"id":"oypef","text":"7"},{"id":"ooi6j","text":"12"},{"id":"ofcom","text":"34"}]}]},{"num":4,"section":"arr","stem":"The 1D array <code>Scores</code> stores 8 test scores:","figure":"<table class=\"gt\"><tr><th>Index</th><td class=\"given\">1</td><td class=\"given\">2</td><td class=\"given\">3</td><td class=\"given\">4</td><td class=\"given\">5</td><td class=\"given\">6</td><td class=\"given\">7</td><td class=\"given\">8</td></tr><tr><th><code>Scores</code></th><td class=\"given\">45</td><td class=\"given\">72</td><td class=\"given\">38</td><td class=\"given\">91</td><td class=\"given\">60</td><td class=\"given\">72</td><td class=\"given\">55</td><td class=\"given\">83</td></tr></table>","parts":[{"id":"4a","label":"(a)","type":"select","marks":3,"prompt":"This program finds the total, the average, the highest score and how many scores are 70 or more. Choose the missing parts.","code":true,"template":"Total ← 0\nHighest ← Scores[1]\nCount ← 0\nFOR Index ← 1 TO 8\n  Total ← Total + Scores[Index]\n  IF Scores[Index] > {{0}}\n    THEN\n      Highest ← {{1}}\n  ENDIF\n  IF Scores[Index] >= 70\n    THEN\n      Count ← {{2}}\n  ENDIF\nNEXT Index\nAverage ← {{3}}","gaps":[{"options":["Count","Highest","Index","Total"]},{"options":["Index","Scores[1]","Scores[Index]","Highest + 1"]},{"options":["1","Count + 1","Count + Scores[Index]","Index"]},{"options":["Total / 8","Total / Index","Total * 8","Count / 8"]}]},{"id":"4b","label":"(b)","type":"select","marks":2,"prompt":"Choose the value of each variable after the program in (a) has run.","template":"<table class=\"gt\"><tr><th>Variable</th><th>Value</th></tr><tr><td class=\"l\"><code>Total</code></td><td>{{0}}</td></tr><tr><td class=\"l\"><code>Average</code></td><td>{{1}}</td></tr><tr><td class=\"l\"><code>Highest</code></td><td>{{2}}</td></tr><tr><td class=\"l\"><code>Count</code></td><td>{{3}}</td></tr></table>","gaps":[{"options":["506","516","526","8"]},{"options":["64","64.5","65","72"]},{"options":["72","83","91","8"]},{"options":["2","3","4","5"]}]},{"id":"4c","label":"(c)","type":"mcq","marks":1,"prompt":"A student finds the lowest score with <code>Lowest ← 0</code> before the loop and <code>IF Scores[Index] &lt; Lowest</code> inside it. What is output as the lowest score?","options":[{"id":"oyt5n","text":"0"},{"id":"o5vz2","text":"38"},{"id":"o1g6f","text":"45"},{"id":"o1kjy","text":"91"}]}]},{"num":5,"section":"arr","stem":"The 2D array <code>Marks[1:3, 1:4]</code> stores the marks of 3 students (rows) in 4 tests (columns):","figure":"<table class=\"gt\"><tr><th><code>Marks</code></th><th>Column 1</th><th>Column 2</th><th>Column 3</th><th>Column 4</th></tr><tr><th>Row 1</th><td class=\"given\">12</td><td class=\"given\">15</td><td class=\"given\">9</td><td class=\"given\">14</td></tr><tr><th>Row 2</th><td class=\"given\">18</td><td class=\"given\">7</td><td class=\"given\">11</td><td class=\"given\">16</td></tr><tr><th>Row 3</th><td class=\"given\">10</td><td class=\"given\">19</td><td class=\"given\">13</td><td class=\"given\">8</td></tr></table>","parts":[{"id":"5a","label":"(a)","type":"mcq","marks":1,"prompt":"What is the value of <code>Marks[2, 3]</code>?","options":[{"id":"o1rj3","text":"11"},{"id":"o1vhv","text":"13"},{"id":"os98i","text":"19"},{"id":"o129l","text":"9"}]},{"id":"5b","label":"(b)","type":"select","marks":3,"prompt":"Complete this program so it finds the <b>largest</b> mark in the whole array.","code":true,"template":"Largest ← Marks[1, 1]\nFOR Row ← 1 TO {{0}}\n  FOR Col ← 1 TO {{1}}\n    IF Marks[Row, Col] > Largest\n      THEN\n        Largest ← {{2}}\n    ENDIF\n  NEXT {{3}}\nNEXT Row\nOUTPUT Largest","gaps":[{"options":["3","4","12","Col"]},{"options":["3","4","12","Row"]},{"options":["Marks[Col, Row]","Marks[Row, Col]","Row","Col"]},{"options":["Col","Largest","Marks","Row"]}]},{"id":"5c","label":"(c)","type":"mcq","marks":1,"prompt":"If the <code>&gt;</code> in (b) were changed to <code>&lt;</code>, what would be output?","options":[{"id":"oxl4m","text":"7"},{"id":"o46ea","text":"8"},{"id":"o1dji","text":"12"},{"id":"o8opd","text":"19"}]},{"id":"5d","label":"(d)","type":"mcq","marks":1,"prompt":"What is output?","listing":"Total ← 0\nFOR Col ← 1 TO 4\n  Total ← Total + Marks[2, Col]\nNEXT Col\nOUTPUT Total","options":[{"id":"o1cib","text":"52"},{"id":"o1gyb","text":"50"},{"id":"omvoa","text":"41"},{"id":"oaqwo","text":"33"}]}]},{"num":6,"section":"alg","stem":"This question is about a linear search and a bubble sort.","parts":[{"id":"6a","label":"(a)","type":"select","marks":3,"prompt":"This linear search looks for <code>Target</code> in the 10-element array <code>Names</code> and stops as soon as it is found. Choose the missing parts.","code":true,"template":"Found ← FALSE\nIndex ← 1\nWHILE Found = {{0}} AND Index <= 10 DO\n  IF Names[Index] = Target\n    THEN\n      Found ← {{1}}\n    ELSE\n      Index ← {{2}}\n  ENDIF\nENDWHILE\nIF Found = TRUE\n  THEN\n    OUTPUT \"Found at position \", Index\n  ELSE\n    OUTPUT \"Not found\"\nENDIF","gaps":[{"options":["FALSE","TRUE","Target","0"]},{"options":["FALSE","TRUE","Index","Target"]},{"options":["1","Index - 1","Index + 1","10"]}]},{"id":"6b","label":"(b)","type":"mcq","marks":1,"prompt":"Why does this search use a WHILE loop and not a FOR loop?","options":[{"id":"o1clh","text":"It can stop as soon as the item is found, instead of always checking all 10 elements."},{"id":"o1o9d","text":"FOR loops cannot be used with arrays."},{"id":"o1pe3","text":"A WHILE loop always runs exactly 10 times."},{"id":"oi0jw","text":"A FOR loop would sort the array first."}]},{"id":"6c","label":"(c)","type":"select","marks":2,"prompt":"A bubble sort puts the values into <b>ascending</b> order. Show the array after the <b>first pass</b>.","lead":"The array <code>List</code> contains:<table class=\"gt\"><tr><th>Index</th><td class=\"given\">1</td><td class=\"given\">2</td><td class=\"given\">3</td><td class=\"given\">4</td><td class=\"given\">5</td></tr><tr><th><code>List</code></th><td class=\"given\">5</td><td class=\"given\">2</td><td class=\"given\">8</td><td class=\"given\">1</td><td class=\"given\">4</td></tr></table>","template":"<table class=\"gt\"><tr><th>Index</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr><tr><td class=\"given\">Pass 1</td><td>{{0}}</td><td>{{1}}</td><td>{{2}}</td><td>{{3}}</td><td>{{4}}</td></tr></table>","gaps":[{"options":["1","2","4","5","8"]},{"options":["1","2","4","5","8"]},{"options":["1","2","4","5","8"]},{"options":["1","2","4","5","8"]},{"options":["1","2","4","5","8"]}]},{"id":"6d","label":"(d)","type":"select","marks":2,"prompt":"Complete the code that swaps two neighbouring elements.","code":true,"template":"IF List[Index] > List[Index + 1]\n  THEN\n    Temp ← {{0}}\n    List[Index] ← {{1}}\n    List[Index + 1] ← {{2}}\n    Swapped ← TRUE\nENDIF","gaps":[{"options":["List[Index]","List[Index + 1]","Temp","Index"]},{"options":["List[Index]","List[Index + 1]","Temp","Index"]},{"options":["List[Index]","List[Index + 1]","Temp","Index"]}]},{"id":"6e","label":"(e)","type":"mcq","marks":1,"prompt":"What is the purpose of the <code>Swapped</code> variable in a bubble sort?","options":[{"id":"o1uhe","text":"If a whole pass makes no swaps, the list is sorted and the algorithm can stop early."},{"id":"o12gc","text":"It stores the value that is being moved."},{"id":"o155a","text":"It counts how many values are in the array."},{"id":"omuoi","text":"It makes the sort go into descending order."}]}]},{"num":7,"section":"str","stem":"This question is about string handling and mathematical operations.","parts":[{"id":"7a","label":"(a)","type":"select","marks":2,"prompt":"Choose the value of each expression.","lead":"<code>Word</code> stores <code>\"Computer\"</code>. In <code>SUBSTRING(String, Start, Length)</code>, the first character is position 1.","template":"<table class=\"gt\"><tr><th>Expression</th><th>Value</th></tr><tr><td class=\"l\"><code>LENGTH(Word)</code></td><td>{{0}}</td></tr><tr><td class=\"l\"><code>SUBSTRING(Word, 4, 3)</code></td><td>{{1}}</td></tr><tr><td class=\"l\"><code>UCASE(Word)</code></td><td>{{2}}</td></tr><tr><td class=\"l\"><code>SUBSTRING(Word, LENGTH(Word) - 1, 2)</code></td><td>{{3}}</td></tr></table>","gaps":[{"options":["7","8","9","\"Computer\""]},{"options":["\"mpu\"","\"put\"","\"pute\"","\"ute\""]},{"options":["\"Computer\"","\"COMPUTER\"","\"computer\"","\"C\""]},{"options":["\"er\"","\"te\"","\"r\"","\"ter\""]}]},{"id":"7b","label":"(b)","type":"select","marks":2,"prompt":"Choose the value of each expression.","template":"<table class=\"gt\"><tr><th>Expression</th><th>Value</th></tr><tr><td class=\"l\"><code>MOD(23, 5)</code></td><td>{{0}}</td></tr><tr><td class=\"l\"><code>DIV(23, 5)</code></td><td>{{1}}</td></tr><tr><td class=\"l\"><code>ROUND(7.468, 1)</code></td><td>{{2}}</td></tr><tr><td class=\"l\"><code>ROUND(7.468, 2)</code></td><td>{{3}}</td></tr></table>","gaps":[{"options":["3","4","4.6","5"]},{"options":["3","4","4.6","5"]},{"options":["7","7.4","7.5","7.47"]},{"options":["7.46","7.47","7.5","7.468"]}]},{"id":"7c","label":"(c)","type":"select","marks":2,"prompt":"This program converts a number of minutes into hours and minutes, then says whether the number of minutes is even. Choose the missing parts.","code":true,"template":"INPUT TotalMins\nHours ← {{0}}(TotalMins, 60)\nMins ← {{1}}(TotalMins, 60)\nOUTPUT Hours, \" hours \", Mins, \" minutes\"\nIF MOD(TotalMins, 2) = {{2}}\n  THEN\n    OUTPUT \"Even\"\nENDIF","gaps":[{"options":["DIV","MOD","ROUND","LENGTH"]},{"options":["DIV","MOD","ROUND","LENGTH"]},{"options":["0","1","2","60"]}]},{"id":"7d","label":"(d)","type":"mcq","marks":1,"prompt":"Which expression always gives the <b>last character</b> of <code>Word</code>, whatever its length?","options":[{"id":"o11wy","text":"SUBSTRING(Word, LENGTH(Word), 1)","code":true},{"id":"o12nm","text":"SUBSTRING(Word, 1, LENGTH(Word))","code":true},{"id":"o126k","text":"SUBSTRING(Word, 8, 1)","code":true},{"id":"o9099","text":"LENGTH(Word)","code":true}]}]},{"num":8,"section":"sub","stem":"This question is about functions and file handling.","parts":[{"id":"8a","label":"(a)","type":"select","marks":2,"prompt":"Complete this function, which returns the area of a rectangle.","code":true,"template":"FUNCTION Area(Length : REAL, Width : REAL) {{0}} REAL\n  {{1}} Length * Width\n{{2}}","gaps":[{"options":["OF","RETURN","RETURNS","THEN"]},{"options":["CALL","OUTPUT","RETURN","RETURNS"]},{"options":["ENDFUNCTION","ENDIF","ENDPROCEDURE","NEXT"]}]},{"id":"8b","label":"(b)","type":"select","marks":2,"prompt":"Choose the value output by each line.","listing":"FUNCTION IsMultiple(N : INTEGER) RETURNS BOOLEAN\n  IF MOD(N, 3) = 0\n    THEN\n      RETURN TRUE\n    ELSE\n      RETURN FALSE\n  ENDIF\nENDFUNCTION","template":"<table class=\"gt\"><tr><th>Statement</th><th>Output</th></tr><tr><td class=\"given\"><code>OUTPUT IsMultiple(9)</code></td><td>{{0}}</td></tr><tr><td class=\"given\"><code>OUTPUT IsMultiple(10)</code></td><td>{{1}}</td></tr><tr><td class=\"given\"><code>OUTPUT IsMultiple(0)</code></td><td>{{2}}</td></tr></table>","gaps":[{"options":["TRUE","FALSE","0","3"]},{"options":["TRUE","FALSE","0","3"]},{"options":["TRUE","FALSE","0","3"]}]},{"id":"8c","label":"(c)","type":"mcq","marks":1,"prompt":"Which statement about procedures and functions is correct?","options":[{"id":"onxge","text":"A function returns a value and is used in an expression; a procedure is run with CALL."},{"id":"o1ylx","text":"A procedure returns a value; a function does not."},{"id":"o108j","text":"Only procedures can have parameters."},{"id":"o1t0p","text":"A function is run with CALL and cannot be used in an expression."}]},{"id":"8d","label":"(d)","type":"select","marks":2,"prompt":"This code stores a player’s name in a text file. Choose the missing parts.","code":true,"template":"INPUT PlayerName\nOPENFILE \"Scores.txt\" FOR {{0}}\n{{1}} \"Scores.txt\", PlayerName\n{{2}} \"Scores.txt\"","gaps":[{"options":["APPEND","READ","WRITE","OUTPUT"]},{"options":["OUTPUT","READFILE","WRITEFILE","INPUT"]},{"options":["CLOSE","CLOSEFILE","ENDFILE","STOP"]}]}]}]};
